package com.rustypayments.internal;

import com.rustypayments.PaymentCalendar;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Set;

/**
 * Modern implementation of PaymentCalendar using java.time API.
 * All calculations are performed in Europe/Warsaw timezone.
 * Thread-safe: uses only immutable objects and thread-safe formatters.
 */
public final class ModernPaymentCalendar implements PaymentCalendar {

    private static final ZoneId WARSAW_ZONE = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    private static final DateTimeFormatter INSTANT_FORMATTER = DateTimeFormatter.ISO_OFFSET_DATE_TIME;

    // Bank holidays: month (1-12), day
    private static final Set<MonthDay> HOLIDAYS = Set.of(
        MonthDay.of(1, 1),   // New Year
        MonthDay.of(1, 6),   // Epiphany
        MonthDay.of(5, 1),   // Labour Day
        MonthDay.of(5, 3),   // Constitution Day
        MonthDay.of(8, 15),  // Assumption
        MonthDay.of(11, 1),  // All Saints
        MonthDay.of(11, 11), // Independence Day
        MonthDay.of(12, 25), // Christmas
        MonthDay.of(12, 26)  // Boxing Day
    );

    private static final LocalTime CUTOFF_TIME = LocalTime.of(16, 0, 0);

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate localDate = parseDate(date);
        return isBusinessDay(localDate);
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime warsawTime = parseInstant(submittedAt).withZoneSameInstant(WARSAW_ZONE);
        LocalDate localDate = warsawTime.toLocalDate();
        LocalTime localTime = warsawTime.toLocalTime();

        if (isBusinessDay(localDate) && !localTime.isAfter(CUTOFF_TIME)) {
            return localDate.format(DATE_FORMATTER);
        }

        LocalDate nextBusinessDay = nextBusinessDay(localDate);
        return nextBusinessDay.format(DATE_FORMATTER);
    }

    @Override
    public String settlementDate(String submittedAt) {
        String processingDateStr = processingDate(submittedAt);
        LocalDate processingDate = parseDate(processingDateStr);
        LocalDate settlementDate = nextBusinessDay(processingDate);
        return settlementDate.format(DATE_FORMATTER);
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseDate(dueDate);
        ZonedDateTime paidWarsaw = parseInstant(paidAt).withZoneSameInstant(WARSAW_ZONE);
        LocalDate paidDate = paidWarsaw.toLocalDate();

        if (paidDate.isBefore(due) || paidDate.isEqual(due)) {
            return 0;
        }

        return (int) ChronoUnit.DAYS.between(due, paidDate);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate start = parseDate(date);
        boolean isMonthEnd = isMonthEnd(start);

        LocalDate result = start.plusMonths(months);

        if (isMonthEnd) {
            // If original was month end, result should be month end of target month
            result = result.withDayOfMonth(result.lengthOfMonth());
        } else {
            // Otherwise, clamp to last day of month if day doesn't exist
            // (handled automatically by plusMonths in java.time)
        }

        return result.format(DATE_FORMATTER);
    }

    private boolean isBusinessDay(LocalDate date) {
        DayOfWeek dayOfWeek = date.getDayOfWeek();
        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
            return false;
        }
        MonthDay monthDay = MonthDay.from(date);
        return !HOLIDAYS.contains(monthDay);
    }

    private LocalDate nextBusinessDay(LocalDate from) {
        LocalDate candidate = from.plusDays(1);
        while (!isBusinessDay(candidate)) {
            candidate = candidate.plusDays(1);
        }
        return candidate;
    }

    private boolean isMonthEnd(LocalDate date) {
        return date.getDayOfMonth() == date.lengthOfMonth();
    }

    private LocalDate parseDate(String text) {
        if (text == null || text.isEmpty()) {
            throw new IllegalArgumentException("INVALID DATE");
        }
        try {
            // This will reject invalid dates like 2026-02-30, 2026-13-01, etc.
            LocalDate date = LocalDate.parse(text, DATE_FORMATTER);
            // Additional validation: ensure the formatted date matches input exactly
            // This catches cases like "2026-3-5" (should be "2026-03-05")
            if (!date.format(DATE_FORMATTER).equals(text)) {
                throw new IllegalArgumentException("INVALID DATE: " + text);
            }
            return date;
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID DATE: " + text);
        }
    }

    private ZonedDateTime parseInstant(String text) {
        if (text == null || text.isEmpty()) {
            throw new IllegalArgumentException("INVALID TIMESTAMP");
        }
        try {
            // Parse as OffsetDateTime first (requires offset), then convert to ZonedDateTime
            OffsetDateTime offsetDateTime = OffsetDateTime.parse(text, INSTANT_FORMATTER);
            return offsetDateTime.toZonedDateTime();
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("INVALID TIMESTAMP: " + text);
        }
    }
}

